/* walker theme — generated by theme-set, do not edit manually */

/* ── Palette ──────────────────────────────────────────────────────────────── */
@define-color selected-text #7aa2f7;
@define-color text          #a9b1d6;
@define-color base          #1a1b26;
@define-color border        #7aa2f7;
@define-color foreground    #a9b1d6;
@define-color background    #1a1b26;

/* ── Reset ────────────────────────────────────────────────────────────────── */
* {
  all: unset;
}

* {
  font-family: "JetBrainsMono Nerd Font", monospace;
  font-size: 14px;
  color: @text;
}

/* ── Scrollbar — hide it, it's visual noise ───────────────────────────────── */
scrollbar {
  opacity: 0;
}

/* ── Icon sizes ───────────────────────────────────────────────────────────── */
.normal-icons {
  -gtk-icon-size: 16px;
}

.large-icons {
  -gtk-icon-size: 32px;
}

/* ── Outer window ─────────────────────────────────────────────────────────── */
.box-wrapper {
  background: alpha(@base, 0.97);
  padding: 20px;
  border: 2px solid @border;
}

/* ── Inner layout boxes (no extra styling needed) ─────────────────────────── */
.box {
}

.preview-box {
}

/* ── Search input ─────────────────────────────────────────────────────────── */
.search-container {
  background: @base;
  padding: 10px;
}

.input placeholder {
  opacity: 0.5;
}

.input {
}

.input:focus,
.input:active {
  box-shadow: none;
  outline: none;
}

/* ── Results list ─────────────────────────────────────────────────────────── */
.content-container {
}

.placeholder {
}

.scroll {
}

.list {
}

/* ── List items ───────────────────────────────────────────────────────────── */
child,
child > * {
}

child:hover .item-box {
}

child:selected .item-box {
}

child:selected .item-box * {
  color: @selected-text;
}

.item-box {
  padding-left: 14px;
}

.item-text-box {
  all: unset;
  padding: 14px 0;
}

.item-text {
}

/* Sub-text hidden — keeps the list clean */
.item-subtext {
  font-size: 0px;
  min-height: 0px;
  margin: 0px;
  padding: 0px;
}

.item-image {
  margin-right: 14px;
  -gtk-icon-transform: scale(0.9);
}

/* Italic label on the currently-running app entry */
.current {
  font-style: italic;
}

/* ── Keybind hints bar ────────────────────────────────────────────────────── */
/* hide_action_hints = true in config.toml, but style it anyway */
.keybind-hints {
  background: @background;
  padding: 10px;
  margin-top: 10px;
}

/* ── Preview pane (unused in default layout) ──────────────────────────────── */
.preview {
}

